const crypto = require('crypto');
const input = $input.first().json;
const body = input.body;
const headers = input.headers || {};
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const signature = String(headers['x-lendloop-signature'] || '');
const secret = $env.CONVEX_TO_N8N_SECRET;
if (!secret || !body || typeof body.eventId !== 'string' || Object.keys(body).length !== 1 || !/^\d{13}$/.test(timestamp) || Math.abs(Date.now() - Number(timestamp)) > 300000 || !/^[a-f0-9]{64}$/.test(signature)) throw new Error('Invalid signed request');
const expected = crypto.createHmac('sha256', secret).update(`v1.${timestamp}.POST.request-notification.${body.eventId}`).digest();
if (!crypto.timingSafeEqual(expected, Buffer.from(signature, 'hex'))) throw new Error('Invalid signed request');
const outboundSecret = $env.N8N_TO_CONVEX_SECRET;
const base = $env.CONVEX_SITE_URL;
if (!outboundSecret || !base) throw new Error('Automation is not configured');
const path = '/automation/notification';
const rawBody = JSON.stringify({ eventId: body.eventId });
const time = String(Date.now());
return [{json:{url:base.replace(/\/$/, '') + path, rawBody, timestamp:time, signature:crypto.createHmac('sha256', outboundSecret).update(`v1.${time}.POST.${path}.${rawBody}`).digest('hex')}}];
